package com.smart.android.ad_app.google.ima.local.signal.module;
import java.io.*;import java.nio.*;import java.security.*;import java.security.cert.*;import java.security.spec.*;import java.util.*;
/** Independent pinned APK Signature Scheme v2 verifier used by zzno.
 * Verifies signed-data, certificate/key agreement and the complete chunked APK
 * digest before returning signer certificate bytes. No package-manager trust
 * shortcut, IMA classes or already-computed SDK result is used. */
public final class ApkV2SignatureVerifier {
 public static final class NotSigned extends IOException{public NotSigned(String message){super(message);}}
 private ApkV2SignatureVerifier(){}
 private static ByteBuffer little(byte[] b){return ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN);}
 private static byte[] read(RandomAccessFile f,long off,int size)throws IOException{if(off<0||size<0)throw new IOException("Invalid APK range");byte[] b=new byte[size];f.seek(off);f.readFully(b);return b;}
 private static ByteBuffer part(ByteBuffer from)throws IOException{if(from.remaining()<4)throw new IOException("Truncated length field");int size=from.getInt();if(size<0||size>from.remaining())throw new IOException("Invalid length field");ByteBuffer out=from.slice().order(ByteOrder.LITTLE_ENDIAN);((Buffer)out).limit(size);((Buffer)from).position(from.position()+size);return out;}
 private static byte[] bytes(ByteBuffer from)throws IOException{ByteBuffer p=part(from);byte[] b=new byte[p.remaining()];p.get(b);return b;}
 private static int digestAlgorithm(int signature){switch(signature){case 257:case 259:case 513:case 769:return 1;case 258:case 260:case 514:return 2;default:return 0;}}
 private static String digestName(int digest){return digest==1?"SHA-256":"SHA-512";}
 private static byte[] le32(long n){return new byte[]{(byte)n,(byte)(n>>>8),(byte)(n>>>16),(byte)(n>>>24)};}
 public static List<List<byte[]>> verify(File actualApk)throws IOException,GeneralSecurityException {
  try(RandomAccessFile file=new RandomAccessFile(actualApk,"r")){
   long length=file.length();if(length<22)throw new NotSigned("ZIP end record absent");int tail=(int)Math.min(length,65557);byte[] end=read(file,length-tail,tail);int index=-1;for(int i=end.length-22;i>=0;i--)if(little(end).getInt(i)==0x06054b50&&i+22+((end[i+20]&255)|((end[i+21]&255)<<8))==end.length){index=i;break;}
   if(index<0)throw new NotSigned("ZIP end record absent");long eocdOffset=length-tail+index;if(eocdOffset>=20&&little(read(file,eocdOffset-20,4)).getInt()==0x07064b50)throw new NotSigned("ZIP64 APK not supported");byte[] eocd=Arrays.copyOfRange(end,index,end.length);ByteBuffer eb=little(eocd);long cdOffset=eb.getInt(16)&0xffffffffL,cdSize=eb.getInt(12)&0xffffffffL;if(cdOffset>=eocdOffset||cdOffset+cdSize!=eocdOffset)throw new NotSigned("Invalid central directory");if(cdOffset<32)throw new NotSigned("APK signing block absent");byte[] footer=read(file,cdOffset-24,24);ByteBuffer fb=little(footer);byte[] magic=Arrays.copyOfRange(footer,8,24);if(!Arrays.equals(magic,"APK Sig Block 42".getBytes("UTF-8")))throw new NotSigned("APK signing block magic absent");long size=fb.getLong(0);if(size<24||size>Integer.MAX_VALUE-8L)throw new NotSigned("APK signing block size invalid");long blockOffset=cdOffset-size-8;if(blockOffset<0)throw new NotSigned("APK signing block offset invalid");ByteBuffer block=little(read(file,blockOffset,(int)size+8));if(block.getLong(0)!=size)throw new NotSigned("APK signing block sizes differ");((Buffer)block).position(8);((Buffer)block).limit(block.capacity()-24);ByteBuffer v2=null;while(block.hasRemaining()){if(block.remaining()<8)throw new NotSigned("Truncated signing entry");long entry=block.getLong();if(entry<4||entry>Integer.MAX_VALUE||entry>block.remaining())throw new NotSigned("Invalid signing entry length");int next=block.position()+(int)entry;int id=block.getInt();if(id==0x7109871a){v2=block.slice().order(ByteOrder.LITTLE_ENDIAN);((Buffer)v2).limit((int)entry-4);break;}((Buffer)block).position(next);}if(v2==null)throw new NotSigned("APK v2 signature absent");
   Map<Integer,byte[]> digests=new HashMap<Integer,byte[]>();List<List<byte[]>> signers=new ArrayList<List<byte[]>>();ByteBuffer signerSequence=part(v2);while(signerSequence.hasRemaining())signers.add(signer(part(signerSequence),digests));if(signers.isEmpty())throw new SecurityException("No signers found");if(digests.isEmpty())throw new SecurityException("No content digests found");
   eb.putInt(16,(int)blockOffset);for(Map.Entry<Integer,byte[]> digest:digests.entrySet()){byte[] computed=contentDigest(file,digest.getKey(),blockOffset,cdOffset,eocdOffset,eocd);if(!MessageDigest.isEqual(digest.getValue(),computed))throw new SecurityException("APK content digest mismatch");}return signers;
  }catch(BufferUnderflowException invalid){throw new SecurityException("Malformed APK signature structure",invalid);}
 }
 private static List<byte[]> signer(ByteBuffer signer,Map<Integer,byte[]> contentDigests)throws IOException,GeneralSecurityException{
  ByteBuffer signed=part(signer),signatures=part(signer);byte[] key=bytes(signer);List<Integer> signatureIds=new ArrayList<Integer>();int selected=-1;byte[] chosen=null;while(signatures.hasRemaining()){ByteBuffer record=part(signatures);if(record.remaining()<8)throw new SecurityException("Signature record too short");int id=record.getInt();signatureIds.add(id);int digest=digestAlgorithm(id);if(digest!=0&&(selected==-1||digest>digestAlgorithm(selected))){selected=id;chosen=bytes(record);}}
  if(selected<0)throw new SecurityException("No supported signatures found");String keyAlgorithm=selected<513?"RSA":selected<769?"EC":"DSA",signatureAlgorithm;AlgorithmParameterSpec parameters=null;switch(selected){case 257:signatureAlgorithm="SHA256withRSA/PSS";parameters=new PSSParameterSpec("SHA-256","MGF1",MGF1ParameterSpec.SHA256,32,1);break;case 258:signatureAlgorithm="SHA512withRSA/PSS";parameters=new PSSParameterSpec("SHA-512","MGF1",MGF1ParameterSpec.SHA512,64,1);break;case 259:signatureAlgorithm="SHA256withRSA";break;case 260:signatureAlgorithm="SHA512withRSA";break;case 513:signatureAlgorithm="SHA256withECDSA";break;case 514:signatureAlgorithm="SHA512withECDSA";break;case 769:signatureAlgorithm="SHA256withDSA";break;default:throw new SecurityException("Unsupported signature algorithm");}
  PublicKey publicKey=KeyFactory.getInstance(keyAlgorithm).generatePublic(new X509EncodedKeySpec(key));Signature verifier=Signature.getInstance(signatureAlgorithm);verifier.initVerify(publicKey);if(parameters!=null)verifier.setParameter(parameters);verifier.update(signed.duplicate());if(!verifier.verify(chosen))throw new SecurityException("APK signed-data signature mismatch");
  ByteBuffer digestSequence=part(signed);List<Integer> digestIds=new ArrayList<Integer>();byte[] digestBytes=null;while(digestSequence.hasRemaining()){ByteBuffer d=part(digestSequence);if(d.remaining()<8)throw new IOException("Digest record too short");int id=d.getInt();digestIds.add(id);if(id==selected)digestBytes=bytes(d);}if(!signatureIds.equals(digestIds))throw new SecurityException("APK digest/signature algorithms differ");int algorithm=digestAlgorithm(selected);byte[] prior=contentDigests.put(algorithm,digestBytes);if(prior!=null&&!MessageDigest.isEqual(prior,digestBytes))throw new SecurityException("APK signer content digests disagree");
  ByteBuffer certificates=part(signed);List<byte[]> raw=new ArrayList<byte[]>();List<X509Certificate> parsed=new ArrayList<X509Certificate>();CertificateFactory factory=CertificateFactory.getInstance("X.509");while(certificates.hasRemaining()){byte[] cert=bytes(certificates);parsed.add((X509Certificate)factory.generateCertificate(new ByteArrayInputStream(cert)));raw.add(cert);}if(parsed.isEmpty())throw new SecurityException("No certificates listed");if(!Arrays.equals(key,parsed.get(0).getPublicKey().getEncoded()))throw new SecurityException("APK certificate/public key mismatch");return raw;
 }
 private static byte[] contentDigest(RandomAccessFile file,int algorithm,long block,long cd,long eocdOffset,byte[] eocd)throws IOException,GeneralSecurityException{
  long chunks=((block+1048575)/1048576)+((eocdOffset-cd+1048575)/1048576)+((eocd.length+1048575L)/1048576);if(chunks>=2097151)throw new SecurityException("Too many APK chunks");MessageDigest total=MessageDigest.getInstance(digestName(algorithm));total.update((byte)0x5a);total.update(le32(chunks));digestSection(file,0,block,null,algorithm,total);digestSection(file,cd,eocdOffset-cd,null,algorithm,total);digestSection(null,0,eocd.length,eocd,algorithm,total);return total.digest();
 }
 private static void digestSection(RandomAccessFile file,long start,long length,byte[] memory,int algorithm,MessageDigest total)throws IOException,GeneralSecurityException{long offset=0;while(offset<length){int size=(int)Math.min(1048576,length-offset);MessageDigest chunk=MessageDigest.getInstance(digestName(algorithm));chunk.update((byte)0xa5);chunk.update(le32(size));if(memory==null)chunk.update(read(file,start+offset,size));else chunk.update(memory,(int)offset,size);total.update(chunk.digest());offset+=size;}}
}
